using System;
using System.Collections.Generic;
using System.IO;
using System.Text.Json;

namespace PZWorkshopDownloader.Services;

public class AppSettings
{
    // The folder mods get downloaded/installed into. Used as both the
    // "PZ Folder" shown on the Updater tab and the download destination
    // on the Downloader tab -- kept as a single unified setting.
    public string ModsFolder { get; set; } = "";

    public bool BackupUpdatedMods { get; set; } = false;
    public string Theme { get; set; } = "Dark"; // Default | Dark | Midnight | Forest
    public bool DebugLogging { get; set; } = false;
    public bool AutoRefreshOnTabSwitch { get; set; } = false;

    // workshopId -> the Steam "hcontent_file" manifest id recorded at the
    // moment we last downloaded that mod. Compared against the live Steam
    // value to detect whether the actual file content has changed --
    // this is the real "version" identifier, not a date.
    public Dictionary<string, string> LocalModVersions { get; set; } = new();

    // workshopId -> local timestamp (ISO 8601) of when we last installed/updated it.
    public Dictionary<string, string> InstallDates { get; set; } = new();

    // ================= Items 4-6: UI customization =================
    // Font sizes (WPF device-independent units). Sliders in Settings write
    // these; MainWindow applies them as app-level DynamicResources so the
    // whole UI picks them up live.
    public double FontSizeGeneral { get; set; } = 12.5;
    public double FontSizeButtons { get; set; } = 12.5;
    public double FontSizeTabHeaders { get; set; } = 13.0;
    public double FontSizeLog { get; set; } = 11.0;
}

public static class SettingsService
{
    private static readonly string SettingsPath = Path.Combine(
        Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
        "PZWorkshopDownloader", "settings.json");

    public static AppSettings Load()
    {
        try
        {
            if (File.Exists(SettingsPath))
            {
                var json = File.ReadAllText(SettingsPath);
                var settings = JsonSerializer.Deserialize<AppSettings>(json);
                if (settings != null) return settings;
            }
        }
        catch
        {
            // Corrupt or unreadable settings file -- fall back to defaults.
        }
        return new AppSettings();
    }

    public static void Save(AppSettings settings)
    {
        try
        {
            var dir = Path.GetDirectoryName(SettingsPath)!;
            Directory.CreateDirectory(dir);
            var json = JsonSerializer.Serialize(settings, new JsonSerializerOptions { WriteIndented = true });
            File.WriteAllText(SettingsPath, json);
        }
        catch
        {
            // Best-effort persistence; not fatal if it fails.
        }
    }
}

