namespace PZWorkshopDownloader.Services;

public static class DownloadHistoryStore
{
    private const int MaxEntries = 300;

    private static readonly string FilePath = Path.Combine(
        Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
        "PZWorkshopDownloader", "download_history.json");

    public static List<DownloadHistoryEntry> Load()
    {
        try
        {
            if (File.Exists(FilePath))
            {
                var json = File.ReadAllText(FilePath);
                var list = JsonSerializer.Deserialize<List<DownloadHistoryEntry>>(json);
                if (list != null) return list;
            }
        }
        catch
        {
            // Corrupt or unreadable -- start fresh rather than crash.
        }
        return new List<DownloadHistoryEntry>();
    }

    public static void Save(List<DownloadHistoryEntry> entries)
    {
        try
        {
            if (entries.Count > MaxEntries)
                entries = entries.GetRange(0, MaxEntries); // list is newest-first

            var dir = Path.GetDirectoryName(FilePath)!;
            Directory.CreateDirectory(dir);
            var json = JsonSerializer.Serialize(entries, new JsonSerializerOptions { WriteIndented = true });
            File.WriteAllText(FilePath, json);
        }
        catch
        {
            // Best-effort persistence; not fatal if it fails.
        }
    }
}

