using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Text.Json;
using System.Threading.Tasks;

namespace PZWorkshopDownloader.Services;

/// <summary>
/// One mod's visual + classification data pulled from Steam's public
/// GetPublishedFileDetails endpoint: the preview image URL and the tag list.
/// WorkshopApiService is intentionally untouched (it stays minimal), so this
/// service exists to grab the extra fields (preview_url / tags) the app now
/// needs for thumbnails and the tag filter sidebar. Requests are batched
/// (up to 100 ids per call) so one request covers all installed mods.
/// </summary>
public class WorkshopVisual
{
    public string Id { get; set; } = "";
    public string PreviewUrl { get; set; } = "";
    public List<string> Tags { get; set; } = new();
}

public static class WorkshopVisualService
{
    private const string Endpoint =
        "https://api.steampowered.com/ISteamRemoteStorage/GetPublishedFileDetails/v1/";

    private const int MaxPerRequest = 100;

    private static readonly HttpClient Http = new();

    /// <summary>
    /// Fetches preview_url + tags for the given workshop ids in as few API
    /// calls as possible. Never throws for an individual item; a hard network
    /// failure throws and is caught by the caller.
    /// </summary>
    public static async Task<Dictionary<string, WorkshopVisual>> GetVisualsAsync(IEnumerable<string> ids)
    {
        var idList = ids.Where(id => !string.IsNullOrEmpty(id)).Distinct().ToList();
        var result = new Dictionary<string, WorkshopVisual>(StringComparer.Ordinal);

        foreach (var chunk in Chunks(idList, MaxPerRequest))
        {
            var content = new Dictionary<string, string> { ["itemcount"] = chunk.Count.ToString() };
            for (int i = 0; i < chunk.Count; i++)
                content[$"publishedfileids[{i}]"] = chunk[i];

            var resp = await Http.PostAsync(Endpoint, new FormUrlEncodedContent(content));
            resp.EnsureSuccessStatusCode();

            using var doc = JsonDocument.Parse(await resp.Content.ReadAsStringAsync());
            var list = doc.RootElement.GetProperty("response").GetProperty("publishedfiledetails");

            foreach (var el in list.EnumerateArray())
            {
                var id = GetString(el, "publishedfileid");
                if (id == null) continue;

                var visual = new WorkshopVisual
                {
                    Id = id,
                    PreviewUrl = GetString(el, "preview_url") ?? "",
                };
                if (el.TryGetProperty("tags", out var tags) && tags.ValueKind == JsonValueKind.Array)
                {
                    foreach (var t in tags.EnumerateArray())
                        if (t.ValueKind == JsonValueKind.Object && t.TryGetProperty("tag", out var tag))
                            visual.Tags.Add(tag.ToString());
                }
                result[id] = visual;
            }
        }
        return result;
    }

    private static IEnumerable<List<string>> Chunks(List<string> list, int size)
    {
        for (int i = 0; i < list.Count; i += size)
            yield return list.GetRange(i, Math.Min(size, list.Count - i));
    }

    private static string? GetString(JsonElement el, string prop) =>
        el.TryGetProperty(prop, out var v) && v.ValueKind != JsonValueKind.Null ? v.ToString() : null;
}

