using System;
using System.Collections.Generic;
using System.Collections.ObjectModel;
using System.Linq;
using System.Windows;
using System.Windows.Controls;

namespace PZWorkshopDownloader;

/// <summary>
/// One row in the Show-Deps dialog: a dependency's display title, its
/// resolved workshop id (null when only an internal name is known), whether
/// it's currently missing, and the buttons shown for it.
/// </summary>
public class DepDisplay
{
    public string Identifier { get; set; } = "";   // raw require= value ("NeatUI_Framework" or "123456")
    public string Title { get; set; } = "";         // best-known display name
    public string? WorkshopId { get; set; }         // real numeric id if resolved, else null
    public bool IsMissing { get; set; }

    public bool CanQueue => WorkshopId != null;
    public string SubText => WorkshopId != null
        ? (IsMissing ? "Missing" : "Installed") + $"  (id {WorkshopId})"
        : "Missing — no workshop id known";
}

public partial class DepsDialog : Window
{
    private readonly Action<DepDisplay> _queueOne;
    private readonly Action<DepDisplay> _openPage;

    public DepsDialog(
        string modName,
        IEnumerable<DepDisplay> deps,
        Action<DepDisplay> queueOne,
        Action<DepDisplay> openPage)
    {
        InitializeComponent();
        _queueOne = queueOne;
        _openPage = openPage;

        HeaderText.Text = $"Dependencies of \"{modName}\"";
        DepsList.ItemsSource = new ObservableCollection<DepDisplay>(deps);

        int unknown = deps.Count(d => d.WorkshopId == null);
        FooterText.Text = unknown > 0
            ? $"{unknown} dependenc{(unknown == 1 ? "y" : "ies")} had no numeric workshop id and will open a Steam search instead."
            : "All dependencies have known workshop ids.";
    }

    /// <summary>
    /// Surface a non-fatal lookup error (e.g. the Workshop page couldn't be
    /// fetched). Keeps the dialog usable for any locally-known dependencies;
    /// "Add All" is disabled since the list may be incomplete.
    /// </summary>
    public void ShowError(string message)
    {
        AddAllButton.IsEnabled = false;
        FooterText.Text = message;
        FooterText.Foreground = System.Windows.Media.Brushes.OrangeRed;
    }

    private void AddAll_Click(object sender, RoutedEventArgs e)
    {
        foreach (var d in DepsList.Items.OfType<DepDisplay>().Where(d => d.CanQueue))
            _queueOne(d);
    }

    private void QueueOne_Click(object sender, RoutedEventArgs e)
    {
        if (sender is FrameworkElement fe && fe.Tag is DepDisplay d && d.CanQueue)
            _queueOne(d);
    }

    private void OpenPage_Click(object sender, RoutedEventArgs e)
    {
        if (sender is FrameworkElement fe && fe.Tag is DepDisplay d)
            _openPage(d);
    }
}

