private static void ClearCache_Click(object sender, RoutedEventArgs e)
{
    var confirm = MessageBox.Show(
        "This will delete all cached mod content files downloaded by SteamCMD. " +
        "Your installed mods and the SteamCMD tool itself are NOT affected.\n\n" +
        "Proceed?", "Clear Workshop Cache",
        MessageBoxButton.YesNo, MessageBoxImage.Warning);
    if (confirm != MessageBoxResult.Yes) return;

    try
    {
        var cache = SteamCmdService.WorkshopCacheDir;
        if (!Directory.Exists(cache))
        {
            AppendLog("No cached workshop files found — nothing to clear.");
            MessageBox.Show("No cached files found.", "Clear Cache",
                MessageBoxButton.OK, MessageBoxImage.Information);
            return;
        }

        foreach (var dir in Directory.GetDirectories(cache))
            Directory.Delete(dir, true);

        AppendLog($"Workshop cache cleared ({cache}).");
        var count = Directory.EnumerateFileSystemEntries(cache).Count();
        StatusText.Text = $"Cache cleared — {count} items remaining.";
    }
    catch (Exception ex)
    {
        AppendLog($"Failed to clear cache: {ex.Message}", "ERROR");
        MessageBox.Show($"Could not clear the cache:\n{ex.Message}", "Clear Cache",
            MessageBoxButton.OK, MessageBoxImage.Error);
    }
}

