display.text:
using System;
using System.Diagnostics;
using System.Windows;

namespace PZWorkshopDownloader;

public partial class AboutWindow : Window
{
    // No repository has been created for this project yet. Once you publish
    // one, replace this constant with the real URL and the button below
    // will link straight to it.
    public const string GitHubUrl = "https://github.com/IDRdh7/PZWorkshopDownloader";
    private const bool GitHubConfigured = true;

    public const string AppVersion = "1.0.0";

    public AboutWindow()
    {
        InitializeComponent();
        VersionText.Text = $"Version {AppVersion}";
    }

    private void GitHubButton_Click(object sender, RoutedEventArgs e)
    {
        try
        {
            Process.Start(new ProcessStartInfo(GitHubUrl) { UseShellExecute = true });
        }
        catch (Exception ex)
        {
            MessageBox.Show($"Could not open browser: {ex.Message}");
        }
    }

    private void Close_Click(object sender, RoutedEventArgs e) => Close();
}
